// index.js (or App.js)
import React from 'react';
import ReactDOM from 'react-dom';
import 'carbon-components/css/carbon-components.min.css';
import { ContentSwitcher, Switch } from 'carbon-components-react';

function Demo() {
  const handleOnChange = (event) => {
    console.log('Switched to tab index:', event.index);
  };

  return (
    <div
      style={{
        backgroundColor: '#161616',
        padding: '2rem',
        color: '#fff',
        minHeight: '200px',
      }}
    >
      <h2 style={{ color: '#fff' }}>Default ContentSwitcher on ui-01</h2>
      <ContentSwitcher onChange={handleOnChange} selectedIndex={0}>
        <Switch name="option-1" text="By reviewer" />
        <Switch name="option-2" text="By account" />
      </ContentSwitcher>

      <div style={{ height: '2rem' }} />

      <h2 style={{ color: '#fff' }}>Light variant ContentSwitcher on ui-01</h2>
      <ContentSwitcher onChange={handleOnChange} selectedIndex={0} light>
        <Switch name="option-1" text="By reviewer" />
        <Switch name="option-2" text="By account" />
      </ContentSwitcher>
    </div>
  );
}

ReactDOM.render(<Demo />, document.getElementById('root'));
